public class TarArchiveInputStream_getNextTarEntry_TriageGen0Test {

    /**
     * Helper to create a minimal valid tar header (512 bytes)
     * Format: Name (100), Mode (8), UID (8), GID (8), Size (12), Mtime (12), Checksum (6), Type (1), Link (100), etc.
     */
    private byte[] createTarHeader(String name, long size, byte typeFlag) {
        byte[] header = new byte[512];
        byte[] nameBytes = name.getBytes();
        System.arraycopy(nameBytes, 0, header, 0, Math.min(nameBytes.length, 100));

        // Size field at offset 124 (octal string)
        String sizeStr = Long.toOctalString(size);
        byte[] sizeBytes = sizeStr.getBytes();
        for (int i = 0; i < sizeBytes.length && i < 12; i++) {
            header[124 + i] = sizeBytes[i];
        }

        header[156] = typeFlag; // Type flag

        // Checksum calculation is complex, but for simple tests, 
        // we can use a real TarArchiveOutputStream to generate valid bytes.
        return header;
    }

    @Test
    public void testGetNextTarEntry_EmptyStream() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            Assert.assertNull(tais.getNextTarEntry());
        }
    }

    @Test
    public void testGetNextTarEntry_SingleEntry() throws IOException {
        // We use a real TarArchiveOutputStream to generate valid test data 
        // to ensure the internal state (headerBuf, entrySize, etc.) is correctly populated.
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);

        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(5);
        taos.putArchiveEntry(entry);
        taos.write("hello".getBytes());
        taos.closeArchiveEntry();
        taos.close();

        InputStream is = new ByteArrayInputStream(baos.toByteArray());
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            TarArchiveEntry result = tais.getNextTarEntry();
            Assert.assertNotNull(result);
            Assert.assertEquals("test.txt", result.getName());
            Assert.assertEquals(5, result.getSize());

            // Second call should be null (EOF)
            Assert.assertNull(tais.getNextTarEntry());
        }
    }

    @Test
    public void testGetNextTarEntry_MultipleEntriesWithSkip() throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);

        // Entry 1
        TarArchiveEntry e1 = new TarArchiveEntry("e1.txt");
        e1.setSize(3);
        taos.putArchiveEntry(e1);
        taos.write("abc".getBytes());
        taos.closeArchiveEntry();

        // Entry 2
        TarArchiveEntry e2 = new TarArchiveEntry("e2.txt");
        e2.setSize(2);
        taos.putArchiveEntry(e2);
        taos.write("de".getBytes());
        taos.closeArchiveEntry();

        taos.close();

        InputStream is = new ByteArrayInputStream(baos.toByteArray());
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            TarArchiveEntry res1 = tais.getNextTarEntry();
            Assert.assertEquals("e1.txt", res1.getName());

            // This triggers the 'if (currEntry != null)' block and the 'skip' logic
            TarArchiveEntry res2 = tais.getNextTarEntry();
            Assert.assertEquals("e2.txt", res2.getName());
            Assert.assertNull(tais.getNextTarEntry());
        }
    }

    @Test
    public void testGetNextTarEntry_GNU_LongName() throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);

        // Using a very long name to trigger GNU LongName logic
        String longName = "this_is_a_very_long_filename_that_exceeds_the_standard_100_character_limit_of_tar_headers_to_force_gnu_format.txt";
        TarArchiveEntry e1 = new TarArchiveEntry(longName);
        e1.setSize(0);
        taos.putArchiveEntry(e1);
        taos.closeArchiveEntry();

        taos.close();

        InputStream is = new ByteArrayInputStream(baos.toByteArray());
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            TarArchiveEntry res = tais.getNextTarEntry();
            Assert.assertNotNull(res);
            Assert.assertEquals(longName, res.getName());
        }
    }

    @Test
    public void testGetNextTarEntry_PaxHeader() throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);

        // Pax headers are triggered by specific metadata in TarArchiveOutputStream
        TarArchiveEntry e1 = new TarArchiveEntry("pax.txt");
        e1.setCreationTime(new java.util.Date(123456789L));
        e1.setSize(4);
        taos.putArchiveEntry(e1);
        taos.write("test".getBytes());
        taos.closeArchiveEntry();

        taos.close();

        InputStream is = new ByteArrayInputStream(baos.toByteArray());
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            TarArchiveEntry res = tais.getNextTarEntry();
            Assert.assertNotNull(res);
            Assert.assertEquals("pax.txt", res.getName());
        }
    }

    @Test
    public void testGetNextTarEntry_GNUSparse() throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);

        // Create a sparse file
        TarArchiveEntry e1 = new TarArchiveEntry("sparse.txt");
        e1.setSize(1024 * 1024); // 1MB
        // Note: Standard TarArchiveOutputStream might not produce sparse type automatically 
        // without specific internal calls, but we test the branch coverage if the stream provides it.
        // For the purpose of this test, we assume the library handles it if the header is present.

        taos.putArchiveEntry(e1);
        taos.closeArchiveEntry();
        taos.close();

        InputStream is = new ByteArrayInputStream(baos.toByteArray());
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            TarArchiveEntry res = tais.getNextTarEntry();
            Assert.assertNotNull(res);
        }
    }

    @Test(expected = RuntimeException.class)
    public void testGetNextTarEntry_SkipFailure() throws IOException {
        // Create a custom InputStream that fails on skip to trigger the RuntimeException
        InputStream failingSkipStream = new InputStream() {
            @Override
            public int read() throws IOException { return -1; }
            @Override
            public long skip(long n) throws IOException { return 0; } // Fail skip
        };

        // We need to trick the parser into thinking there is an entry to skip
        // This is hard with a raw stream, so we simulate the state via a subclass or complex mock
        // But since we can't easily mock the internal state 'currEntry', we'll simulate it 
        // by providing a stream that returns a valid header then fails on skip.

        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
            new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(baos);
        TarArchiveEntry e1 = new TarArchiveEntry("e1.txt");
        e1.setSize(10);
        taos.putArchiveEntry(e1);
        taos.write(new byte[10]);
        taos.closeArchiveEntry();
        taos.close();

        // Mocking the skip failure by wrapping the stream
        InputStream wrapped = new InputStream() {
            InputStream delegate = new ByteArrayInputStream(baos.toByteArray());
            boolean skipFailed = false;
            @Override
            public int read() throws IOException { return delegate.read(); }
            @Override
            public long skip(long n) throws IOException {
                if (skipFailed) return 0;
                long s = delegate.skip(n);
                // After first entry, trigger failure
                if (delegate.available() < 512) { skipFailed = true; return 0; }
                return s;
            }
            @Override
            public int available() throws IOException { return delegate.available(); }
        };

        try (TarArchiveInputStream tais = new TarArchiveInputStream(wrapped)) {
            tais.getNextTarEntry(); // Read first
            tais.getNextTarEntry(); // This should trigger skip and fail
        }
    }
}
